7:
8:type MouchBind = (e: cg.MouchEvent) => void;
9:type StateMouchBind = (d: State, e: cg.MouchEvent) => void;
10:
11:export function bindBoard(s: State, onResize: () => void): void {
12:  const boardEl = s.dom.elements.board;
13:
14:  if ('ResizeObserver' in window) new ResizeObserver(onResize).observe(s.dom.elements.wrap);
15:
16:  if (s.disableContextMenu || s.drawable.enabled) {
17:    boardEl.addEventListener('contextmenu', e => e.preventDefault());
18:  }
19:
20:  if (s.viewOnly) return;
21:
22:  // Cannot be passive, because we prevent touch scrolling and dragging of
23:  // selected elements.
24:  const onStart = startDragOrDraw(s);
25:  boardEl.addEventListener('touchstart', onStart as EventListener, {
26:    passive: false,
27:  });
28:  boardEl.addEventListener('mousedown', onStart as EventListener, {
29:    passive: false,
30:  });
31:}
32:
33:// returns the unbind function
34:export function bindDocument(s: State, onResize: () => void): cg.Unbind {
35:  const unbinds: cg.Unbind[] = [];
36:
37:  // Old versions of Edge and Safari do not support ResizeObserver. Send
38:  // chessground.resize if a user action has changed the bounds of the board.
39:  if (!('ResizeObserver' in window)) unbinds.push(unbindable(document.body, 'chessground.resize', onResize));
40:
41:  if (!s.viewOnly) {
42:    const onmove = dragOrDraw(s, drag.move, draw.move);
43:    const onend = dragOrDraw(s, drag.end, draw.end);
44:
45:    for (const ev of ['touchmove', 'mousemove'])
46:      unbinds.push(unbindable(document, ev, onmove as EventListener));
47:    for (const ev of ['touchend', 'mouseup']) unbinds.push(unbindable(document, ev, onend as EventListener));
48:
49:    const onScroll = () => s.dom.bounds.clear();
50:    unbinds.push(unbindable(document, 'scroll', onScroll, { capture: true, passive: true }));
51:    unbinds.push(unbindable(window, 'resize', onScroll, { passive: true }));
52:  }
53:
54:  return () => unbinds.forEach(f => f());
55:}
56:
57:function unbindable(
58:  el: EventTarget,
59:  eventName: string,
60:  callback: EventListener,
61:  options?: AddEventListenerOptions,
62:): cg.Unbind {
63:  el.addEventListener(eventName, callback, options);
64:  return () => el.removeEventListener(eventName, callback, options);
65:}
